            if (ClothRegion524.Enabled || ClothRegion524.UseAreaCurves532 || !post || post.candidateEnabled || HeadRegion502.Enabled || HeadRegion502.UseAutomaticCurve511 || HeadRegion502.UseBodyRay512)
                throw new Exception("Current baseline flags changed; preserve and inspect");
            prior = f.validateRender;
            if (prior != null && prior.GetInvocationList().Any(x => !(x.Target is PostView366)))
                throw new Exception("Other capture hook active");
            if (Directory.Exists(Root))
                throw new Exception("Live output exists; no duplicate capture");
            Directory.CreateDirectory(Root);
            File.WriteAllText(Root + "face_before.txt", FaceState524.Snapshot(h));
            oldCurve = ClothRegion524.UseOpacityCurves527;
            oldArea = ClothRegion524.UseAreaCurves532;
            oldIndex = ClosedRegion524.UseSpatialIndex526;
            oldMove = move.enabled;
            oldAnim = a.enabled;
