            oldLoc = a.GetFloat("LocomotionSpeed");
            oldSpeed = a.speed;
            oldCapture = Time.captureDeltaTime;
            oldRotation = a.transform.rotation;
            var state = a.GetCurrentAnimatorStateInfo(0);
            oldState = state.fullPathHash;
            oldTime = state.normalizedTime;
            sky.SetAutomaticAdvance(false);
            move.enabled = false;
            a.enabled = true;
            a.speed = 1;
            a.SetFloat("LocomotionSpeed", 1);
            a.transform.rotation = Quaternion.Euler(0, 80, 0);
            a.Play(oldState, 0, 1f + (firstFrame - 1) / 80f + .00000248f);
            a.Update(0);
            Time.captureDeltaTime = 1f / 60;
            Application.runInBackground = true;
            count = 0;
            queued = false;
            deadline = EditorApplication.timeSinceStartup + 600;
            f.validateRender = OnFinal;
            EditorApplication.update += Tick;
            File.WriteAllText(Root + "comparison.txt", "same execution:527 clothing ON baseline vs532 clothing ON alternative; product default OFF; range " + firstFrame + ".." + lastFrame);
            File.WriteAllText(Root + "started.json", "{\"firstFrame\":" + firstFrame + ",\"lastFrame\":" + lastFrame + ",\"pairs\":" + (lastFrame - firstFrame + 1) + ",\"postEnabled\":false,\"candidateDefaultOFF\":true,\"sameFrozenPoseRenders\":2,\"note\":\"actual Walk advances between captures; each observed pose paused then rendered twice; restore on completion/error\"}");
        }
