    public static class FaceState524
    {
        static string Tex(Texture t) => t ? t.GetEntityId() + ":" + t.name + ":" + AssetDatabase.GetAssetPath(t) : "null";
        static void Material(StringBuilder b, string n, Material m)
        {
            b.Append(n + "=");
            if (!m)
            {
                b.AppendLine("null");
                return;
            }

            b.Append(m.GetEntityId() + ":" + m.name + ":" + (m.shader ? m.shader.name : "null"));
            if (m.HasProperty("_MainTex"))
                b.Append(" tex=" + Tex(m.GetTexture("_MainTex")));
            if (m.HasProperty("_Color"))
                b.Append(" colour=" + m.GetColor("_Color").ToString("R"));
            b.AppendLine();
        }

        public static string Snapshot(HeadLocal367 h)
        {
            var b = new StringBuilder();
            b.AppendLine("headEnabled=" + h.headEnabled + " proofOnly=" + FullFeature367.proofOnly);
            int side = 0;
            foreach (var f in new[]{h.main, h.head})
            {
                if (!f)
                {
                    b.AppendLine("missing full");
                    continue;
                }

                b.AppendLine("side=" + side + " style=" + f.styleEnabled + " stock=" + f.stockMode + " faceMain=" + f.faceMain + " provider=" + f.faceProvider + " integrated=" + f.integrated);
                var camera = f.motion.camera;
                b.AppendLine("camera=" + camera.GetEntityId() + " enabled=" + camera.enabled + " culling=" + camera.cullingMask + " target=" + Tex(camera.targetTexture));
                Material(b, "providerMat", f.legacyProviderMat);
                for (int j = 0; j < f.motion.materials.Length; j++)
                    Material(b, "source" + j, f.motion.materials[j]);
                for (int j = 0; j < f.independentMats.Length; j++)
                    Material(b, "independent" + j, f.independentMats[j]);
                foreach (var r in new Renderer[]{f.motion.surface.source[1], f.motion.surface.outputs[1].GetComponent<Renderer>()})
                {
                    if (!r)
                        continue;
                    var block = new MaterialPropertyBlock();
                    r.GetPropertyBlock(block);
                    b.AppendLine("renderer=" + r.GetEntityId() + " enabled=" + r.enabled + " layer=" + r.gameObject.layer + " active=" + r.gameObject.activeInHierarchy + " blockEmpty=" + block.isEmpty + " blockTex=" + Tex(block.GetTexture("_MainTex")) + " blockColour=" + block.GetColor("_Color").ToString("R"));
                    foreach (var mat in r.sharedMaterials)
                        Material(b, "rendererMat", mat);
                }

                side++;
            }

            return b.ToString();
        }
    }
